import{_ as e,o as d,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const m=JSON.parse('{"title":"Results","description":"Property reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started.","frontmatter":{"title":"Results","description":"Property reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started."},"headers":[],"relativePath":"nestjs-myanmar-payments/references/results.md","filePath":"nestjs-myanmar-payments/references/results.md"}'),a={name:"nestjs-myanmar-payments/references/results.md"};function c(n,t,s,i,h,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns one of four classes from <code>@laranex/myanmar-payments</code>. Their union is the <code>PaymentResult</code> type, and each exposes <code>flow: PaymentFlow</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>kbzPay().pwa()</code> and <code>waveMoney().initiate()</code>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>gatewayReference</code></td><td><code>string | undefined</code></td><td>The gateway&#39;s ID for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>Readonly&lt;Record&lt;string, unknown&gt;&gt;</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>ayaPay().initiate()</code> and <code>cyberSource().initiate()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>action</code></td><td><code>string</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>fields</code></td><td><code>readonly FormField[]</code></td><td>The signed hidden fields (<code>name</code>, <code>value</code>), in signing order. Post them unchanged</td></tr><tr><td><code>enctype</code></td><td><code>string</code></td><td>The form encoding the gateway expects</td></tr><tr><td><code>field(name)</code></td><td><code>string | undefined</code></td><td>The value of one field</td></tr><tr><td><code>values()</code></td><td><code>Record&lt;string, string&gt;</code></td><td>The fields as an object, e.g. for your own template</td></tr><tr><td><code>toHtml()</code></td><td><code>string</code></td><td>A full HTML page that posts the form on load</td></tr></tbody></table><p><code>this.payments.autoSubmitUrl(payment)</code> returns the link to the module&#39;s auto-submitting page. It throws when the form route is disabled.</p><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>kbzPay().qr()</code>, <code>yomaMmqr().initiate()</code> and <code>yomaMmqr().renewQr()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>qrString</code></td><td><code>string | undefined</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>qrImage</code></td><td><code>string | undefined</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>expiresAt</code></td><td><code>Date | undefined</code></td><td>When the QR stops being payable</td></tr><tr><td><code>reference</code></td><td><code>string | undefined</code></td><td>The gateway&#39;s ID for this QR (KBZ <code>prepay_id</code>, Yoma <code>refLabel</code>)</td></tr><tr><td><code>raw</code></td><td><code>Readonly&lt;Record&lt;string, unknown&gt;&gt;</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>qrImageDataUri(mimeType = &#39;image/png&#39;)</code></td><td><code>string | undefined</code></td><td><code>qrImage</code> as a data URI for <code>&lt;img src&gt;</code></td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>kbzPay().app()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>orderInfo</code></td><td><code>string</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>sign</code></td><td><code>string</code></td><td>The signature of <code>orderInfo</code></td></tr><tr><td><code>signType</code></td><td><code>string</code></td><td><code>SHA256</code></td></tr><tr><td><code>raw</code></td><td><code>Readonly&lt;Record&lt;string, unknown&gt;&gt;</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>toJSON()</code></td><td><code>object</code></td><td><code>orderId</code>, <code>orderInfo</code>, <code>sign</code>, <code>signType</code> for your mobile app</td></tr></tbody></table><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>String</th><th>Result</th></tr></thead><tbody><tr><td><code>PaymentFlow.Redirect</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>PaymentFlow.Form</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>PaymentFlow.Qr</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>PaymentFlow.App</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table>',17)])])}const p=e(a,[["render",c]]);export{m as __pageData,p as default};
